// SERVER: Socket Creation and Binding (TCP/IPv4)
int sockfd, portno = 8080;
struct sockaddr_in serv_addr;

sockfd = socket(AF_INET, SOCK_STREAM, 0);

// Set SO_REUSEADDR to avoid "Address already in use"
int optval = 1;
setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &optval, sizeof(optval));

serv_addr.sin_family = AF_INET;
serv_addr.sin_addr.s_addr = INADDR_ANY; // Listen on all interfaces
serv_addr.sin_port = htons(portno);

bind(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr));


// SERVER: Listening and Accepting Connection
int newsockfd;
socklen_t clilen;
struct sockaddr_in cli_addr;

listen(sockfd, 5); // Max 5 pending connections in queue

clilen = sizeof(cli_addr);
newsockfd = accept(sockfd, (struct sockaddr *) &cli_addr, &clilen);


// CLIENT: Socket Creation and Connection
int sockfd, portno = 8080;
struct sockaddr_in serv_addr;
struct hostent *server; // Resolve hostname

sockfd = socket(AF_INET, SOCK_STREAM, 0);

server = gethostbyname("127.0.0.1"); // Target server IP/hostname

serv_addr.sin_family = AF_INET;
bcopy((char *)server->h_addr, (char *)&serv_addr.sin_addr.s_addr, server->h_length);
serv_addr.sin_port = htons(portno);

connect(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr));


// DATA TRANSFER: Send and Receive (Blocking I/O)
char buffer[1024];
ssize_t bytes_transferred;

// Sending data
const char* response = "ACK";
bytes_transferred = write(sockfd, response, strlen(response));

// Receiving data
bzero(buffer, 1024);
bytes_transferred = read(sockfd, buffer, 1023);

if (bytes_transferred > 0) {
    // Process buffer...
}

close(sockfd);
shutdown(sockfd, SHUT_RDWR); // Graceful closure (optional)
